#include "game/script_header.hpp"
namespace{std::uint16_t u16(const std::vector<unsigned char>&b,std::size_t p){return p+2<=b.size()?std::uint16_t(b[p])|(std::uint16_t(b[p+1])<<8):0;}std::uint32_t u32(const std::vector<unsigned char>&b,std::size_t p){return p+4<=b.size()?std::uint32_t(b[p])|(std::uint32_t(b[p+1])<<8)|(std::uint32_t(b[p+2])<<16)|(std::uint32_t(b[p+3])<<24):0;}}
HgScriptHeader parse_hg_script_header(const std::vector<unsigned char>& b){HgScriptHeader h;std::size_t p=0;while(p<b.size()){auto type=b[p++];if(type==0){h.valid=true;break;}if(p+4>b.size())return h;auto val=u32(b,p);p+=4;if(type==1){std::size_t q=p+val;if(q>b.size())return h;while(q+6<=b.size()){auto var=u16(b,q);if(var==0)break;h.frame.push_back({var,u16(b,q+2),u16(b,q+4)});q+=6;}}else if(type==2)h.transition=std::uint16_t(val);else if(type==3)h.resume=std::uint16_t(val);else if(type==4)h.load=std::uint16_t(val);else return h;}return h;}
std::uint16_t hg_triggered_frame_script(const HgScriptHeader& h,const HgGameState& s){for(auto const&t:h.frame)if(s.var(t.var)==t.value)return t.script;return 0;}
